async () => { /* S0 baseline: no overlay, no visited pages, Hampshire facts not held */

  const t = window.__test;
  const s = t.getState();
  const g = s.globals;
  const raw = window.gameState.globalVariables.se_osint_state;
  const visited = raw && Array.isArray(raw.visited) ? raw.visited : [];
  return !s.activeMinigame && visited.length === 0 && (raw == null || raw.at == null || raw.at === '')
    && g.se_intel_hampshire_careers === false && g.se_intel_hampshire_cv_backlog === false
    && g.osint_done === false;

}

async () => { /* O1 the workstation opens the browser on the company team page, keyboard-owning, Close is a normal exit, nothing to type */

  const mg = window.MinigameFramework.currentMinigame;
  if (!mg || mg.constructor.name !== 'OsintBrowserMinigame') throw new Error('not the browser');
  const s = mg.getTestState();
  const o = s.osint;
  const ok = s.overlay.sceneType === 'osint-browser' && s.overlay.closeMode === 'close'
    && mg.params.requiresKeyboardInput === true && mg.params.disableClose === true
    && s.overlay.layers.length === 0 && s.overlay.suspended === false && s.overlay.returnsTo === null
    && o.caseFile === true && o.profile === 'student' && o.typedInputs === 0
    && o.view === 'page' && o.location === 'company.team' && o.siteId === 'company' && o.pageId === 'team'
    && o.address === 'ledgerwell.example'
    && o.sites.map(x => x.id).join() === 'company,social,deck'
    && !!mg.container.querySelector('.ob-case') && !!mg.container.querySelector('.ob-close')
    && mg.container.querySelector('.ob-address-text').textContent === 'ledgerwell.example';
  if (!ok) throw new Error('O1 ' + JSON.stringify({ scene: s.overlay.sceneType, close: s.overlay.closeMode, view: o.view, location: o.location, address: o.address, sites: o.sites, typed: o.typedInputs, caseFile: o.caseFile }));
  return true;

}

async () => { /* O2 Space, E, WASD and arrows do nothing while the browser is open (player not moved, no second minigame) */

  const t = window.__test;
  const mg = window.MinigameFramework.currentMinigame;
  const a = t.getState();
  const p0 = { x: a.player.x, y: a.player.y };
  const loc0 = mg.getTestState().osint.location;
  for (const k of [' ', 'e', 'E', 'w', 'a', 's', 'd', 'ArrowUp', 'ArrowLeft', 'ArrowRight', 'ArrowDown']) await t.minigame.pressKey(k);
  await new Promise(r => setTimeout(r, 300));
  const b = t.getState();
  const s = mg.getTestState();
  return b.activeMinigame && b.activeMinigame.id === 'osint-browser' && mg.constructor.name === 'OsintBrowserMinigame'
    && window.MinigameFramework.currentMinigame === mg && s.osint.location === loc0
    && Math.abs(b.player.x - p0.x) < 0.5 && Math.abs(b.player.y - p0.y) < 0.5 && !b.blockingUi;

}

async () => { /* O3 Tab order on the team page: Case file, Close, the sites, the page links, the staff rows, Archive; every control takes focus and none has a positive tabindex */

  const mg = window.MinigameFramework.currentMinigame;

  const sel = 'button, [role=button], a[href], input, select, textarea, [tabindex]';
  const all = [...mg.container.querySelectorAll(sel)].filter(e => e.offsetParent !== null && !e.disabled && e.id !== 'minigame-close');
  const els = all.filter(e => e.tabIndex >= 0);
  const labels = els.map(e => (e.getAttribute('aria-label') || e.innerText || e.value || '').trim().split('\n')[0]);
  const noPositive = all.every(e => !(e.tabIndex > 0));
  let focusFail = null;
  for (const e of all) {
    e.focus();
    if (document.activeElement !== e) { focusFail = (e.tagName + '.' + e.className).slice(0, 80); break; }
  }

  const expect = ['Case file', 'Close', 'Ledgerwell', 'Friendface', 'Q3.pdf', 'Tools', 'Our Team', 'Team notes', 'Careers', 'How to apply', 'Morgan Teague', 'Ravi Shah', 'Chris Hampshire', 'Archive'];
  const match = labels.length === expect.length && expect.every((f, i) => labels[i] === f || (labels[i] || '').startsWith(f));
  if (!noPositive || !match || focusFail || els.length === 0) throw new Error('O3 focus=' + focusFail + ' labels=' + JSON.stringify(labels));
  return true;

}

async () => { /* O4 the document page shows the authored address, and Esc-layer controls in the properties panel take focus in order */

  const mg = window.MinigameFramework.currentMinigame;
  const click = (sel) => { const el = mg.container.querySelector(sel); if (!el) throw new Error('missing ' + sel); el.click(); };
  click('.ob-site[data-site="deck"]');
  const mid = mg.getTestState().osint;
  if (mid.view !== 'document' || mid.location !== 'deck' || mid.address !== 'ledgerwell.example/Q3.pdf' || mid.propertiesOpen !== false) {
    throw new Error('deck ' + JSON.stringify({ view: mid.view, location: mid.location, address: mid.address, propertiesOpen: mid.propertiesOpen }));
  }
  click('.ob-props-open');
  const s = mg.getTestState();
  const dlg = mg.container.querySelector('.ob-props');

  const sel = 'button, [role=button], a[href], input, select, textarea, [tabindex]';
  const all = [...mg.container.querySelectorAll(sel)].filter(e => e.offsetParent !== null && !e.disabled && e.id !== 'minigame-close');
  const els = all.filter(e => e.tabIndex >= 0);
  const labels = els.map(e => (e.getAttribute('aria-label') || e.innerText || e.value || '').trim().split('\n')[0]);
  const noPositive = all.every(e => !(e.tabIndex > 0));
  let focusFail = null;
  for (const e of all) {
    e.focus();
    if (document.activeElement !== e) { focusFail = (e.tagName + '.' + e.className).slice(0, 80); break; }
  }

  const expect = ['Case file', 'Close', 'Ledgerwell', 'Friendface', 'Q3.pdf', 'Tools', 'What is this?', 'Author', 'Software', 'Path', 'Close properties'];
  const match = labels.length === expect.length && expect.every((f, i) => labels[i] === f || (labels[i] || '').startsWith(f));
  const ok = s.osint.propertiesOpen === true && s.osint.view === 'document' && s.osint.location === 'deck'
    && s.overlay.layers.length === 1 && s.overlay.layers[0] === 'document-properties'
    && !!dlg && dlg.getAttribute('role') === 'dialog' && dlg.getAttribute('aria-label') === 'Document properties'
    && noPositive && match && !focusFail;
  if (!ok) throw new Error('O4 focus=' + focusFail + ' layers=' + JSON.stringify(s.overlay.layers) + ' labels=' + JSON.stringify(labels));
  return true;

}

async () => { /* O5 Esc inside the properties panel closes the panel first and leaves the browser on the same document */

  const t = window.__test;
  const mg = window.MinigameFramework.currentMinigame;
  if (!mg || mg.constructor.name !== 'OsintBrowserMinigame') throw new Error('overlay closed');
  const s = mg.getTestState();
  return s.osint.propertiesOpen === false && s.overlay.layers.length === 0
    && s.osint.view === 'document' && s.osint.location === 'deck'
    && s.osint.address === 'ledgerwell.example/Q3.pdf'
    && !!mg.container.querySelector('.ob-props-open')
    && t.getState().activeMinigame && t.getState().activeMinigame.id === 'osint-browser';

}

async () => { /* O6 Esc with no panel open closes the browser with success and logs no minigame_failed */

  const t = window.__test;
  await new Promise(r => setTimeout(r, 300));
  const since = (m) => { const l = t.peekLog(500); let i = -1; l.forEach((e, j) => { if (e.kind === 'note' && e.message === m) i = j; }); return l.slice(i + 1).filter(e => e.kind === 'event'); };
  const evs = since('O6 esc close');
  const c = evs.find(e => e.event === 'minigame_completed' && e.data && e.data.minigameName === 'OsintBrowserMinigame');
  const visited = c && c.data.result && c.data.result.visited;
  return !!c && c.data.success === true && c.data.result && c.data.result.aborted !== true
    && Array.isArray(visited) && visited.includes('deck') && visited.includes('company.team')
    && !evs.some(e => e.event === 'minigame_failed')
    && !t.getState().activeMinigame;

}

async () => { /* O7a reopening the workstation restores the saved document page */

  const mg = window.MinigameFramework.currentMinigame;
  if (!mg || mg.constructor.name !== 'OsintBrowserMinigame') throw new Error('not the browser');
  const o = mg.getTestState().osint;
  const ok = o.location === 'deck' && o.view === 'document' && o.address === 'ledgerwell.example/Q3.pdf'
    && o.visited.includes('deck') && o.visited.includes('company.team');
  if (!ok) throw new Error('O7a ' + JSON.stringify({ location: o.location, view: o.view, address: o.address, visited: o.visited }));
  return true;

}

async () => { /* O7 the browser Close control completes with success and logs no minigame_failed */

  const t = window.__test;
  await new Promise(r => setTimeout(r, 300));
  const since = (m) => { const l = t.peekLog(500); let i = -1; l.forEach((e, j) => { if (e.kind === 'note' && e.message === m) i = j; }); return l.slice(i + 1).filter(e => e.kind === 'event'); };
  const evs = since('O7 close button');
  const c = evs.find(e => e.event === 'minigame_completed' && e.data && e.data.minigameName === 'OsintBrowserMinigame');
  return !!c && c.data.success === true && c.data.result && c.data.result.aborted !== true
    && !evs.some(e => e.event === 'minigame_failed')
    && !t.getState().activeMinigame;

}

async () => { /* O8 Careers and the Hampshire post grant their facts by selecting the blocks, then the browser is back on the Careers page */

  const mg = window.MinigameFramework.currentMinigame;
  const click = (sel) => { const el = mg.container.querySelector(sel); if (!el) throw new Error('missing ' + sel); el.click(); };
  const fontOk = (sel) => { const e = mg.container.querySelector(sel); if (!e) return false; const f = getComputedStyle(e).fontFamily || ''; return /^\s*["']?GNF/i.test(f); }; /* page text is the pixel font; addresses keep Source Sans 3 */
  click('.ob-site[data-site="company"]');
  click('a[data-focus="link:company.careers"]');
  if (mg.getTestState().osint.location !== 'company.careers') throw new Error('not careers ' + mg.getTestState().osint.location);
  click('.ob-block[data-id="careers_inbox"]');
  const g = window.gameState.globalVariables;
  if (g.se_intel_hampshire_careers !== true) throw new Error('careers fact not granted');
  click('.ob-site[data-site="social"]');
  const listed = mg.getTestState();
  if (listed.osint.location !== 'social' || !listed.osint.pages.includes('hampshire')) throw new Error('profile list ' + JSON.stringify({ location: listed.osint.location, pages: listed.osint.pages }));
  click('a[data-focus="profile:hampshire"]');
  if (mg.getTestState().osint.location !== 'social.hampshire') throw new Error('not profile ' + mg.getTestState().osint.location);
  if (mg.getTestState().osint.address !== 'friendface.example') throw new Error('social address ' + mg.getTestState().osint.address);
  click('.ob-block[data-id="post_hampshire_cvs"]');
  if (g.se_intel_hampshire_cv_backlog !== true) throw new Error('backlog fact not granted');
  const postFontOk = fontOk('.ob-post-text');
  if (!postFontOk) throw new Error('F1: .ob-post-text not the readable font');
  click('.ob-site[data-site="company"]');
  click('a[data-focus="link:company.careers"]');
  const s = mg.getTestState();
  const need = ['company', 'company.team', 'deck', 'company.careers', 'social', 'social.hampshire'];
  const have = s.osint.visited;
  const missing = need.filter(id => !have.includes(id));
  const noted = s.osint.blocks.find(b => b.id === 'careers_inbox');
  const ok = s.osint.location === 'company.careers' && s.osint.pageId === 'careers' && s.osint.address === 'ledgerwell.example'
    && missing.length === 0 && s.osint.held.includes('hampshire_careers') && s.osint.held.includes('hampshire_cv_backlog')
    && noted && noted.noted === true
    && g.osint_done === false
    && postFontOk && fontOk('.ob-block-text');
  if (!ok) throw new Error('O8 missing=' + JSON.stringify(missing) + ' visited=' + JSON.stringify(have) + ' location=' + s.osint.location + ' blockFontOk=' + fontOk('.ob-block-text'));
  return true;

}

async () => { /* O9 Case file opens the recon board on top of the browser */

  const t = window.__test;
  const mg = window.MinigameFramework.currentMinigame;
  if (!mg || mg.constructor.name !== 'IntelBoardMinigame') throw new Error('not the board ' + (mg && mg.constructor.name));
  const s = mg.getTestState();
  return t.getState().activeMinigame && t.getState().activeMinigame.id === 'intel-board'
    && s.overlay.sceneType === 'intel-board' && s.overlay.closeMode === 'close'
    && s.board.mode === 'recon' && s.overlay.returnsTo === 'osint-browser'
    && mg.params.requiresKeyboardInput === true;

}

async () => { /* O10 closing the board returns to the same Careers page, with the facts still held and no minigame_failed */

  const t = window.__test;
  await new Promise(r => setTimeout(r, 300));
  const mg = window.MinigameFramework.currentMinigame;
  if (!mg || mg.constructor.name !== 'OsintBrowserMinigame') throw new Error('did not return ' + (mg && mg.constructor.name));
  const s = mg.getTestState();
  const since = (m) => { const l = t.peekLog(500); let i = -1; l.forEach((e, j) => { if (e.kind === 'note' && e.message === m) i = j; }); return l.slice(i + 1).filter(e => e.kind === 'event'); };
  const evs = since('O10 board close');
  const c = evs.find(e => e.event === 'minigame_completed' && e.data && e.data.minigameName === 'IntelBoardMinigame');
  const g = window.gameState.globalVariables;
  const need = ['company', 'company.team', 'deck', 'company.careers', 'social', 'social.hampshire'];
  const missing = need.filter(id => !s.osint.visited.includes(id));
  const failed = evs.filter(e => e.event === 'minigame_failed').map(e => e.data && e.data.minigameName);
  const ok = !!c && c.data.success === true && failed.length === 0
    && t.getState().activeMinigame && t.getState().activeMinigame.id === 'osint-browser'
    && s.osint.location === 'company.careers' && s.osint.pageId === 'careers'
    && s.osint.address === 'ledgerwell.example'
    && s.overlay.suspended === false && s.overlay.returnsTo === null
    && missing.length === 0
    && g.se_intel_hampshire_careers === true && g.se_intel_hampshire_cv_backlog === true
    && s.osint.blocks.some(b => b.id === 'careers_inbox' && b.noted === true);
  if (!ok) throw new Error('O10 ' + JSON.stringify({ success: c && c.data.success, failed, events: evs.map(e => e.event), location: s.osint.location, pageId: s.osint.pageId, missing, returnsTo: s.overlay.returnsTo, suspended: s.overlay.suspended }));
  return true;

}

async () => { /* RELOAD the page reloaded (sentinel gone), the bridge is back and the game is ready */

  const t0 = Date.now();
  while (!(window.__test && window.__test.waitUntilReady) && Date.now() - t0 < 60000) await new Promise(r => setTimeout(r, 250));
  if (window.__preReload) return false;
  const r = await window.__test.waitUntilReady({ timeoutMs: 60000 });
  return !!(r && r.ok);

}

async () => { /* O11 a reload keeps the visited pages and the granted facts */

  const t = window.__test;
  const g = window.gameState.globalVariables;
  const raw = g.se_osint_state;
  const visited = raw && Array.isArray(raw.visited) ? raw.visited : [];
  const need = ['company', 'company.team', 'deck', 'company.careers', 'social', 'social.hampshire'];
  const missing = need.filter(id => !visited.includes(id));
  const ok = !t.getState().activeMinigame && missing.length === 0 && raw && raw.at === 'company.careers'
    && g.se_intel_hampshire_careers === true && g.se_intel_hampshire_cv_backlog === true
    && t.getState().globals.se_intel_hampshire_careers === true;
  if (!ok) throw new Error('O11 at=' + (raw && raw.at) + ' missing=' + JSON.stringify(missing) + ' visited=' + JSON.stringify(visited));
  return true;

}

async () => { /* O12 opening the workstation again lands on the saved Careers page with both facts still noted */

  const mg = window.MinigameFramework.currentMinigame;
  if (!mg || mg.constructor.name !== 'OsintBrowserMinigame') throw new Error('not the browser');
  const s = mg.getTestState();
  const need = ['company', 'company.team', 'deck', 'company.careers', 'social', 'social.hampshire'];
  const noted = s.osint.blocks.find(b => b.id === 'careers_inbox');
  const ok = s.osint.location === 'company.careers' && s.osint.pageId === 'careers'
    && s.osint.address === 'ledgerwell.example'
    && need.every(id => s.osint.visited.includes(id))
    && s.osint.held.includes('hampshire_careers') && s.osint.held.includes('hampshire_cv_backlog')
    && noted && noted.noted === true
    && window.gameState.globalVariables.se_osint_state.at === 'company.careers';
  if (!ok) throw new Error('O12 ' + JSON.stringify({ location: s.osint.location, address: s.osint.address, visited: s.osint.visited, held: s.osint.held, at: window.gameState.globalVariables.se_osint_state && window.gameState.globalVariables.se_osint_state.at }));
  return true;

}
